    w.SetProjectileWeaponLoaded(false, &ammo);
    if (g_copies != 1 || ammo.CopiedFrom != 1 || w.AimingTime != -1 || w.AimingTimeOverride || w.ProjectileWeaponLoaded) FAIL();
